from collections.abc import Callable

import pytest


def wrapped(job: Callable[[], str]) -> str:
    """Execute `job` and return its result enclosed as 'start:' + result + ':end'."""
    return f"start:{job()}:end"


def test_wrapped_simple() -> None:
    assert wrapped(lambda: "hello") == "start:hello:end"


def test_wrapped_empty() -> None:
    assert wrapped(lambda: "") == "start::end"


def test_wrapped_propagates_exception() -> None:
    def failing_job() -> str:
        raise ValueError("failure")

    with pytest.raises(ValueError, match="failure"):
        wrapped(failing_job)


def test_wrapped_calls_job_once() -> None:
    calls: list[int] = []

    def counting_job() -> str:
        calls.append(1)
        return "counted"

    result = wrapped(counting_job)
    assert result == "start:counted:end"
    assert len(calls) == 1

